class StudioShell extends StatefulWidget {
  const StudioShell({super.key});

  @override
  State<StudioShell> createState() => _StudioShellState();
}

class _StudioShellState extends State<StudioShell> {
  int _index = 0;
  final _articleKey = GlobalKey<_ArticlePageState>();

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Row(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          NavigationRail(
            selectedIndex: _index,
            onDestinationSelected: (i) {
              setState(() => _index = i);
              // 从设置页切回文章页时重读服务端连接设置，保证推送用最新值
              if (i == 0) _articleKey.currentState?.reloadRemote();
            },
            labelType: NavigationRailLabelType.all,
            destinations: const [
              NavigationRailDestination(
                icon: Icon(Icons.article_outlined),
                label: Text('文章'),
              ),
              NavigationRailDestination(
                icon: Icon(Icons.image_outlined),
                label: Text('图文'),
              ),
              NavigationRailDestination(
                icon: Icon(Icons.videocam_outlined),
                label: Text('视频'),
              ),
              NavigationRailDestination(
                icon: Icon(Icons.settings_outlined),
                label: Text('设置'),
              ),
            ],
          ),
          const VerticalDivider(width: 1),
          Expanded(
            child: IndexedStack(
              index: _index,
              children: [
                ArticlePage(key: _articleKey),
                const PlaceholderPage(title: '图文'),
                const PlaceholderPage(title: '视频'),
                const SettingsPage(),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

