#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PubArticle {
    pub article_id: String,
    pub title: String,
    pub digest: String,
    pub author: String,
    /// 正文 HTML；列表接口（no_content=1）时为空
    pub content: String,
    pub thumb_url: String,
    /// 公众号文章页 URL
    pub url: String,
    #[serde(default)]
    pub publish_time: u64,
}

