    #[serde(default)]
    content: String,
    #[serde(default)]
    thumb_url: String,
    #[serde(default)]
    url: String,
}

#[derive(Deserialize)]
struct ContentWrap {
    #[serde(default)]
    news_item: Vec<NewsItem>,
}

#[derive(Deserialize)]
struct BatchItem {
