struct BatchResp {
    #[serde(default)]
    total_count: u64,
    #[serde(default)]
    item: Vec<BatchItem>,
}

#[derive(Deserialize)]
struct GetResp {
    #[serde(default)]
    content: Option<ContentWrap>,
    #[serde(default)]
    publish_time: Option<u64>,
}

